new Function('global',src2)(global);
let t=0; const step=()=>{const f=raf;t+=16.67;f(t);};
listeners['wkeydown']({key:' ',preventDefault:noop});
let launches=0, maxFrames=60*60*30, last='';
for(let i=0;i<maxFrames;i++){
  global.__ai();
  const g=global.__g();
  if(g.state==='serve'){listeners['wkeydown']({key:' ',preventDefault:noop});launches++;}
