const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
const src = html.match(/<script>([\s\S]*?)<\/script>/)[1];
new Function(src);
console.log('parse OK');

const listeners = {};
const noop = () => {};
const ctx = new Proxy({}, {
  get: (t, k) => k === 'createLinearGradient' ? () => ({ addColorStop: noop }) : (k in t ? t[k] : noop),
  set: (t, k, v) => { t[k] = v; return true; }
});
const canvas = {
  width: 800, height: 600, getContext: () => ctx,
  addEventListener: (n, f) => { listeners['c' + n] = f; },
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 })
};
let raf = null;
global.document = { getElementById: () => canvas };
global.window = { addEventListener: (n, f) => { listeners['w' + n] = f; } };
global.requestAnimationFrame = f => { raf = f; };

const hook = 'requestAnimationFrame(frame);\n})();';
if (!src.includes(hook)) throw new Error('hook not found');
const src2 = src.replace(hook,
  'requestAnimationFrame(frame);' +
  'global.__g=function(){return {state:state,score:score,lives:lives,level:levelIndex,alive:aliveCount(),ball:ball,paddle:paddle};};' +
  'global.__ai=function(miss){mouseTargetX= miss ? 0 : ball.x+(Math.random()-0.5)*80;};\n})();');
new Function('global', src2)(global);

let t = 0;
const press = () => listeners['wkeydown']({ key: ' ', preventDefault: noop });
function run(missMode) {
  press();
  let last = '', launches = 0;
  for (let i = 0; i < 60 * 60 * 30; i++) {
    global.__ai(missMode);
    const g = global.__g();
    if (g.state === 'serve') { press(); launches++; }
    if (g.state === 'win' || g.state === 'gameover') break;
    const b = g.ball;
    if (g.state === 'play' && (b.x < 0 || b.x > 800 || b.y < 40 - 0.01)) { console.log('OOB', b); break; }
    t += 16.67; raf(t);
    const s = g.state + ':' + g.level;
    if (s !== last) { console.log('  frame', i, s, 'score', g.score, 'lives', g.lives, 'alive', g.alive); last = s; }
  }
  const g = global.__g();
  console.log('final', g.state, 'score', g.score, 'lives', g.lives, 'level', g.level, 'launches', launches);
}
console.log('--- autoplay run'); run(false);
console.log('--- miss run'); run(true);
// pause test
press(); press();
listeners['wkeydown']({ key: 'p', preventDefault: noop });
console.log('after P:', global.__g().state);
listeners['wkeydown']({ key: 'p', preventDefault: noop });
console.log('after P again:', global.__g().state);

